23	+// whether they still exist, never at how a rock or Tux is implemented.
24	+
25	+#include <gtest/gtest.h>
26	+
27	+#include <SDL.h>
28	+#include <SDL_ttf.h>
29	+#include <physfs.h>
30	+
31	+#include <cmath>
32	+#include <memory>
33	+#include <sstream>
34	+#include <string>
35	+#include <vector>
36	+
37	+#include "audio/sound_manager.hpp"
38	+#include "badguy/badguy.hpp"
39	+#include "control/input_manager.hpp"
40	+#include "object/coin.hpp"
41	+#include "object/player.hpp"
42	+#include "object/rock.hpp"
43	+#include "squirrel/squirrel_virtual_machine.hpp"
44	+#include "sprite/sprite_manager.hpp"
45	+#include "supertux/gameconfig.hpp"
46	+#include "supertux/globals.hpp"
47	+#include "supertux/level.hpp"
48	+#include "supertux/level_parser.hpp"
49	+#include "supertux/resources.hpp"
50	+#include "supertux/sector.hpp"
51	+#include "supertux/tile.hpp"
52	+#include "supertux/tile_manager.hpp"
53	+#include "supertux/tile_set.hpp"
54	+#include "video/ttf_surface_manager.hpp"
55	+#include "video/video_system.hpp"
56	+
57	+namespace {
58	+
59	+const float FRAME = 1.0f / 64.0f;
60	+const int LEVEL_W = 40;          // tiles
61	+const int LEVEL_H = 15;          // tiles
62	+const int FLOOR_ROW = 13;        // the floor's top is at y = 416
63	+const float FLOOR_Y = 416.0f;
64	+const float LEDGE_Y = 224.0f;    // ledge tiles on row 7, x tiles 1..8 (right end at x = 288)
65	+const float LEDGE_END = 288.0f;
66	+
67	+/** Brings up the subsystems the game itself starts before it plays a level
68	+    (data files, a headless "null" video system, muted sound, scripting,
69	+    tiles, sprites, fonts). */
70	+class GameEnvironment : public ::testing::Environment
71	+{
72	+public:
73	+  void SetUp() override
74	+  {
75	+    ASSERT_TRUE(PHYSFS_init(nullptr)) << "Could not initialize physfs";
76	+    // The test binary runs from the repository root, so the shipped data/
77	+    // directory can be mounted directly.
78	+    ASSERT_TRUE(PHYSFS_mount("data", nullptr, 1)) << "Could not mount data/";
79	+    ASSERT_EQ(0, SDL_Init(SDL_INIT_TIMER | SDL_INIT_VIDEO | SDL_INIT_JOYSTICK | SDL_INIT_GAMECONTROLLER))
80	+      << SDL_GetError();
81	+    ASSERT_EQ(0, TTF_Init());
82	+
83	+    g_config = std::make_unique<Config>();
84	+    m_input_manager = std::make_unique<InputManager>(g_config->keyboard_config, g_config->joystick_config);
85	+    m_video_system = VideoSystem::create(VideoSystem::VIDEO_NULL);
86	+    m_ttf_surface_manager = std::make_unique<TTFSurfaceManager>();
87	+    m_sound_manager = std::make_unique<SoundManager>();
88	+    m_sound_manager->enable_sound(false);
89	+    m_sound_manager->enable_music(false);
90	+    m_squirrel = std::make_unique<SquirrelVirtualMachine>(false);
91	+    m_tile_manager = std::make_unique<TileManager>();
92	+    m_sprite_manager = std::make_unique<SpriteManager>();
93	+    m_resources = std::make_unique<Resources>();
94	+  }
95	+
96	+  void TearDown() override
97	+  {
98	+    m_resources.reset();
99	+    m_sprite_manager.reset();
100	+    m_tile_manager.reset();
101	+    m_squirrel.reset();
102	+    m_sound_manager.reset();
103	+    m_ttf_surface_manager.reset();
104	+    m_video_system.reset();
105	+    m_input_manager.reset();
106	+    g_config.reset();
107	+    TTF_Quit();
108	+    SDL_Quit();
109	+    PHYSFS_deinit();
110	+  }
111	+
112	+private:
113	+  std::unique_ptr<InputManager> m_input_manager;
114	+  std::unique_ptr<VideoSystem> m_video_system;
115	+  std::unique_ptr<TTFSurfaceManager> m_ttf_surface_manager;
116	+  std::unique_ptr<SoundManager> m_sound_manager;
117	+  std::unique_ptr<SquirrelVirtualMachine> m_squirrel;
118	+  std::unique_ptr<TileManager> m_tile_manager;
119	+  std::unique_ptr<SpriteManager> m_sprite_manager;
120	+  std::unique_ptr<Resources> m_resources;
121	+};
122	+
123	+::testing::Environment* const g_game_environment =
124	+  ::testing::AddGlobalTestEnvironment(new GameEnvironment());
125	+
126	+/** A walled room with a solid floor and, optionally, a ledge in the upper
127	+    left part of the room that ends in open air at x = 288. With a trench,
128	+    two one-tile posts on the floor (x 256..288 and 352..384) fence in the
129	+    floor right below the ledge's end. */
130	+std::string room_tiles(bool ledge, bool trench = false)
131	+{
132	+  std::ostringstream out;
133	+  for (int y = 0; y < LEVEL_H; ++y) {
134	+    for (int x = 0; x < LEVEL_W; ++x) {
135	+      const bool solid = y >= FLOOR_ROW || x == 0 || x == LEVEL_W - 1 ||
136	+                         (ledge && y == 7 && x >= 1 && x <= 8) ||
137	+                         (trench && y == FLOOR_ROW - 1 && (x == 8 || x == 11));
138	+      out << (solid ? 48 : 0) << ' ';
139	+    }
140	+  }
141	+  return out.str();
142	+}
143	+
144	+class Scene
145	+{
146	+public:
147	+  Scene(const std::string& objects, float spawn_x, float spawn_y, bool ledge, bool trench = false) :
148	+    m_level(),
149	+    m_sector(nullptr),
150	+    m_tux(nullptr)
151	+  {
152	+    std::ostringstream lvl;
153	+    lvl << "(supertux-level (version 3) (name \"rock scene\") (author \"tests\") (license \"CC0\")"
154	+        << " (sector (name \"main\") (ambient-light (color 1 1 1))"
155	+        << " (spawnpoint (name \"main\") (x " << spawn_x << ") (y " << spawn_y << "))"
156	+        << " (tilemap (solid #t) (z-pos 0) (width " << LEVEL_W << ") (height " << LEVEL_H << ")"
157	+        << " (tiles " << room_tiles(ledge, trench) << "))"
158	+        << " " << objects << "))";
159	+    std::istringstream in(lvl.str());
160	+    m_level = LevelParser::from_stream(in, "rock-scene", false, false);
161	+    m_sector = m_level->get_sector(0);
162	+    m_sector->activate("main");
163	+    m_tux = &m_sector->get_player();
164	+    m_tux->use_scripting_controller(true);
165	+  }
166	+
167	+  ~Scene()
168	+  {
169	+    m_sector->deactivate();
170	+  }
171	+
172	+  void step(int frames = 1)
173	+  {
174	+    for (int i = 0; i < frames; ++i)
175	+      m_sector->update(FRAME);
176	+  }
177	+
178	+  void press(const std::string& control) { m_tux->do_scripting_controller(control, true); }
179	+  void release(const std::string& control) { m_tux->do_scripting_controller(control, false); }
180	+
181	+  Player& tux() { return *m_tux; }
182	+
183	+  std::vector<Rock*> rocks()
184	+  {
185	+    std::vector<Rock*> out;
186	+    for (auto& rock : m_sector->get_objects_by_type<Rock>())
187	+      out.push_back(&rock);
188	+    return out;
189	+  }
190	+
191	+  Rock* rock_near(float x)
192	+  {
193	+    Rock* best = nullptr;
194	+    for (auto* rock : rocks())
195	+      if (!best || std::abs(rock->get_bbox().get_middle().x - x) < std::abs(best->get_bbox().get_middle().x - x))
196	+        best = rock;
197	+    return best;
198	+  }
199	+
200	+  std::vector<BadGuy*> badguys()
201	+  {
202	+    std::vector<BadGuy*> out;
203	+    for (auto& badguy : m_sector->get_objects_by_type<BadGuy>())
204	+      out.push_back(&badguy);
205	+    return out;
206	+  }
207	+
208	+  size_t coin_count()
209	+  {
210	+    size_t n = 0;
211	+    for (auto& coin : m_sector->get_objects_by_type<Coin>()) { (void)coin; ++n; }
212	+    return n;
213	+  }
214	+
215	+  /** Short taps on "right" so Tux creeps forward instead of sliding past
216	+      the target (a ledge's end, for instance). */
217	+  void creep_right_until(float right_edge)
218	+  {
219	+    for (int i = 0; i < 600 && m_tux->get_bbox().get_right() < right_edge; ++i) {
220	+      press("right");
221	+      step(2);
222	+      release("right");
223	+      step(10);
224	+    }
225	+    step(30);
226	+  }
227	+
228	+private:
229	+  std::unique_ptr<Level> m_level;
230	+  Sector* m_sector;
231	+  Player* m_tux;
232	+};
233	+
234	+/** Tux picks up the rock lying on the ledge and stands at the ledge's end
235	+    holding it, facing right, over the open air. */
236	+void carry_rock_to_ledge_end(Scene& scene)
237	+{
238	+  scene.step(10);
239	+  scene.press("action");
240	+  scene.creep_right_until(LEDGE_END + 14.0f);
241	+}
242	+
243	+/** Frames until the rock's bottom first reaches the floor, or -1. */
244	+int frames_until_on_floor(Scene& scene, Rock& rock, int max_frames)
245	+{
246	+  for (int i = 1; i <= max_frames; ++i) {
247	+    scene.step();
248	+    if (rock.get_bbox().get_bottom() >= FLOOR_Y - 1.0f)
249	+      return i;
250	+  }
251	+  return -1;
252	+}
253	+
254	+/** Tux walks right (or left) holding a rock and lets go of it mid-stride. */
255	+struct ThrowResult
256	+{
257	+  float release_x;     // rock centre right after it left Tux's hands
258	+  float flight_x;      // rock centre a quarter of a second later
259	+  float tux_x;         // Tux's centre when he let go
260	+};
261	+
262	+ThrowResult throw_while_walking(Scene& scene, const std::string& dir)
263	+{
264	+  scene.step(10);
265	+  scene.press("action");
266	+  scene.press(dir);
267	+  scene.step(48);
268	+  ThrowResult result;
269	+  result.tux_x = scene.tux().get_bbox().get_middle().x;
270	+  scene.release("action");
271	+  scene.step(1);
272	+  scene.release(dir);
273	+  Rock* rock = scene.rocks().front();
274	+  result.release_x = rock->get_bbox().get_middle().x;
275	+  scene.step(16);
276	+  result.flight_x = rock->get_bbox().get_middle().x;
277	+  return result;
278	+}
279	+
280	+} // namespace
281	+
282	+// ---------------------------------------------------------------------------
283	+// Dropping a rock past coins
284	+// ---------------------------------------------------------------------------
285	+
286	+TEST(RockBehaviour, DroppedRockFallsPastCoinsLikeThroughOpenAir)
287	+{
288	+  // Same drop twice: once through open air, once through a column of coins
289	+  // hanging under the ledge's end. The coins must not hold the rock up.
290	+  int open_air = -1;
291	+  {
292	+    Scene scene("(rock (x 200) (y 192))", 96, 160, true);
293	+    carry_rock_to_ledge_end(scene);
294	+    ASSERT_EQ(1u, scene.rocks().size());
295	+    scene.release("action");
296	+    open_air = frames_until_on_floor(scene, *scene.rocks().front(), 256);
297	+    ASSERT_GT(open_air, 0) << "the rock should reach the floor when nothing is in its way";
298	+  }
299	+
300	+  Scene scene("(rock (x 200) (y 192))"
301	+              " (coin (x 306) (y 260)) (coin (x 306) (y 292)) (coin (x 306) (y 324))",
302	+              96, 160, true);
303	+  carry_rock_to_ledge_end(scene);
304	+  Rock& rock = *scene.rocks().front();
305	+  const size_t coins_before = scene.coin_count();
306	+  scene.release("action");
307	+  const int through_coins = frames_until_on_floor(scene, rock, 256);
308	+
309	+  EXPECT_GT(through_coins, 0) << "the dropped rock never reached the floor below the coins";
310	+  EXPECT_LE(through_coins, open_air + 2)
311	+    << "the rock took " << through_coins << " frames to fall past the coins, but only "
312	+    << open_air << " frames to fall the same distance through open air";
313	+  EXPECT_EQ(coins_before, scene.coin_count()) << "a falling rock should not use up coins";
314	+}
315	+
316	+// ---------------------------------------------------------------------------
317	+// Carrying
318	+// ---------------------------------------------------------------------------
319	+
320	+TEST(RockBehaviour, CarriedRockIsHeldInFrontOfTux)
321	+{
322	+  Scene scene("(rock (x 200) (y 384))", 96, 352, false);
323	+  scene.step(10);
324	+  scene.press("action");
325	+  scene.press("right");
326	+  scene.step(40);
327	+  ASSERT_EQ(1u, scene.rocks().size());
328	+  Rock& rock = *scene.rocks().front();
329	+
330	+  for (int i = 0; i < 4; ++i) {
331	+    scene.step(8);
332	+    EXPECT_GT(rock.get_bbox().get_middle().x, scene.tux().get_bbox().get_middle().x)
333	+      << "walking right: the rock (centre x " << rock.get_bbox().get_middle().x
334	+      << ") should be in front of Tux (centre x " << scene.tux().get_bbox().get_middle().x << ")";
335	+  }
336	+
337	+  scene.release("right");
338	+  scene.press("left");
339	+  scene.step(24);
340	+  for (int i = 0; i < 4; ++i) {
341	+    scene.step(8);
342	+    EXPECT_LT(rock.get_bbox().get_middle().x, scene.tux().get_bbox().get_middle().x)
343	+      << "walking left: the rock (centre x " << rock.get_bbox().get_middle().x
344	+      << ") should be in front of Tux (centre x " << scene.tux().get_bbox().get_middle().x << ")";
345	+  }
346	+  scene.release("left");
347	+  scene.release("action");
348	+}
349	+
350	+TEST(RockBehaviour, CarriedRockMovesAlongWithTux)
351	+{
352	+  Scene scene("(rock (x 200) (y 384))", 96, 352, false);
353	+  scene.step(10);
354	+  scene.press("action");
355	+  scene.press("right");
356	+  scene.step(40);
357	+  Rock& rock = *scene.rocks().front();
358	+  const float start = rock.get_bbox().get_middle().x;
359	+  scene.step(40);
360	+  EXPECT_GT(rock.get_bbox().get_middle().x - start, 64.0f) << "the carried rock should travel with Tux";
361	+  EXPECT_LT(std::abs(rock.get_bbox().get_middle().x - scene.tux().get_bbox().get_middle().x), 48.0f);
362	+  EXPECT_LT(rock.get_bbox().get_bottom(), FLOOR_Y) << "the carried rock is lifted off the floor";
363	+  scene.release("right");
364	+  scene.release("action");
365	+}
366	+
367	+// ---------------------------------------------------------------------------
368	+// Throwing
369	+// ---------------------------------------------------------------------------
370	+
371	+TEST(RockBehaviour, RockThrownWhileWalkingFliesForward)
372	+{
373	+  {
374	+    Scene scene("(rock (x 200) (y 384))", 96, 352, false);
375	+    const ThrowResult r = throw_while_walking(scene, "right");
376	+    EXPECT_GT(r.flight_x - r.release_x, 16.0f)
377	+      << "thrown while walking right, the rock moved from x " << r.release_x << " to " << r.flight_x;
378	+  }
379	+  {
380	+    Scene scene("(rock (x 800) (y 384))", 900, 352, false);
381	+    const ThrowResult r = throw_while_walking(scene, "left");
382	+    EXPECT_LT(r.flight_x - r.release_x, -16.0f)
383	+      << "thrown while walking left, the rock moved from x " << r.release_x << " to " << r.flight_x;
384	+  }
385	+}
386	+
387	+TEST(RockBehaviour, ThrownRockLandsAndStaysOnTheGround)
388	+{
389	+  for (const std::string dir : {"right", "left"}) {
390	+    Scene scene(dir == "right" ? "(rock (x 200) (y 384))" : "(rock (x 800) (y 384))",
391	+                dir == "right" ? 96 : 900, 352, false);
392	+    throw_while_walking(scene, dir);
393	+    Rock& rock = *scene.rocks().front();
394	+    scene.step(128);
395	+    const Rectf before = rock.get_bbox();
396	+    scene.step(64);
397	+    EXPECT_NEAR(FLOOR_Y, rock.get_bbox().get_bottom(), 2.0f)
398	+      << "thrown " << dir << ": two seconds later the rock should lie on the floor, its bottom is at y "
399	+      << rock.get_bbox().get_bottom();
400	+    EXPECT_NEAR(before.get_top(), rock.get_bbox().get_top(), 1.0f) << "thrown " << dir << ": the landed rock keeps still";
401	+    EXPECT_NEAR(before.get_left(), rock.get_bbox().get_left(), 1.0f) << "thrown " << dir << ": the landed rock keeps still";
402	+  }
403	+}
404	+
405	+TEST(RockBehaviour, PutDownRockLandsOnTheGround)
406	+{
407	+  Scene scene("(rock (x 200) (y 192))", 96, 160, true);
408	+  carry_rock_to_ledge_end(scene);
409	+  scene.release("action");
410	+  Rock& rock = *scene.rocks().front();
411	+  scene.step(128);
412	+  EXPECT_NEAR(FLOOR_Y, rock.get_bbox().get_bottom(), 2.0f);
413	+}
414	+
415	+// ---------------------------------------------------------------------------
416	+// A rock lying on the ground is solid
417	+// ---------------------------------------------------------------------------
418	+
419	+TEST(RockBehaviour, TuxCanStandOnARestingRock)
420	+{
421	+  Scene scene("(rock (x 320) (y 384))", 320, 160, false);
422	+  scene.step(128);
423	+  Rock& rock = *scene.rocks().front();
424	+  EXPECT_NEAR(rock.get_bbox().get_top(), scene.tux().get_bbox().get_bottom(), 2.0f)
425	+    << "Tux fell onto the rock and should be standing on top of it (rock top y " << rock.get_bbox().get_top()
426	+    << ", Tux bottom y " << scene.tux().get_bbox().get_bottom() << ")";
427	+  scene.step(64);
428	+  EXPECT_NEAR(rock.get_bbox().get_top(), scene.tux().get_bbox().get_bottom(), 2.0f) << "and keep standing there";
429	+  EXPECT_NEAR(FLOOR_Y, rock.get_bbox().get_bottom(), 2.0f) << "the rock itself stays on the floor";
430	+}
431	+
432	+TEST(RockBehaviour, TuxWalkingIntoARestingRockIsStoppedByIt)
433	+{
434	+  Scene scene("(rock (x 320) (y 384))", 160, 352, false);
435	+  scene.step(30);
436	+  scene.press("right");
437	+  scene.step(128);
438	+  Rock& rock = *scene.rocks().front();
439	+  EXPECT_LE(scene.tux().get_bbox().get_right(), rock.get_bbox().get_left() + 2.0f)
440	+    << "Tux walked into the rock without picking it up; he should be stopped by it (Tux right x "
441	+    << scene.tux().get_bbox().get_right() << ", rock left x " << rock.get_bbox().get_left() << ")";
442	+  EXPECT_NEAR(FLOOR_Y, scene.tux().get_bbox().get_bottom(), 2.0f);
443	+  scene.release("right");
444	+}
445	+
446	+TEST(RockBehaviour, RockDroppedOnARestingRockStaysOnTop)
447	+{
448	+  Scene scene("(rock (x 320) (y 384)) (rock (x 322) (y 100))", 96, 352, false);
449	+  scene.step(192);
450	+  Rock* lower = nullptr;
451	+  Rock* upper = nullptr;
452	+  for (auto* rock : scene.rocks()) {
453	+    if (!lower || rock->get_bbox().get_top() > lower->get_bbox().get_top()) { upper = lower; lower = rock; }
454	+    else upper = rock;
455	+  }
456	+  ASSERT_NE(nullptr, upper);
457	+  EXPECT_NEAR(FLOOR_Y, lower->get_bbox().get_bottom(), 2.0f);
458	+  EXPECT_NEAR(lower->get_bbox().get_top(), upper->get_bbox().get_bottom(), 2.0f)
459	+    << "the dropped rock should rest on top of the other one";
460	+}
461	+
462	+// ---------------------------------------------------------------------------
463	+// A rock falling on an enemy
464	+// ---------------------------------------------------------------------------
465	+
466	+TEST(RockBehaviour, RockDroppedOnAWalkingLeafKnocksItOut)
467	+{
468	+  // The leaf paces back and forth in a two-tile trench right below the ledge's
469	+  // end, so wherever in that trench it is, the dropped rock comes down on it.
470	+  Scene scene("(rock (x 200) (y 192)) (walkingleaf (x 304) (y 384) (direction \"left\"))", 96, 160, true, true);
471	+  carry_rock_to_ledge_end(scene);
472	+  ASSERT_EQ(1u, scene.badguys().size());
473	+  const Rectf leaf_box = scene.badguys().front()->get_bbox();
474	+  ASSERT_GE(leaf_box.get_left(), LEDGE_END - 1.0f) << "setup: the leaf should be pacing in the trench";
475	+  ASSERT_LE(leaf_box.get_right(), LEDGE_END + 65.0f) << "setup: the leaf should be pacing in the trench";
476	+  scene.release("action");
477	+  scene.step(64 * 4);
478	+
479	+  bool leaf_still_there = false;
480	+  for (auto* badguy : scene.badguys())
481	+    if (badguy->get_bbox().get_top() < FLOOR_Y)
482	+      leaf_still_there = true;
483	+  EXPECT_FALSE(leaf_still_there)
484	+    << "four seconds after the rock fell on the walking leaf, the leaf is still standing in the room";
485	+}
486	+
487	+/* EOF */
